def is_prime(n: int) -> bool:
    """Return True if n is a positive prime integer, else False."""
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    f = 3
    while f * f <= n:
        if n % f == 0:
            return False
        f += 2
    return True
```

Handles `1` as non-prime, `2` and `3` as prime, evens > 2 as composite, then trial-divides odd factors up to `sqrt(n)`.
